raw = open(P, 'rb').read(); L = raw.decode('utf-8').split('\n')
def head_idx(h):
    idx = [i for i, s in enumerate(L) if s.startswith(h)]
    assert len(idx) == 1, (h, idx)
    return idx[0]
def table_end(h):
    i = head_idx(h) + 1
    while not L[i].startswith('|'): i += 1
    while i < len(L) and L[i].startswith('|'): i += 1
    return i
groups = {}
for h, row in R: groups.setdefault(h, []).append(row)
ops = [(table_end(h), [r[:-1].rstrip() + T + ' |' for r in rows], h) for h, rows in groups.items()]
